/* ---------------------------------------------------------------------------------------------------------------
 * files: the shop and orders-api projects. S.files.shop / S.files.orders are generated by gen-shop.mjs from a real git
 * repository of the sample files (build/shop.json, build/orders.json); see DATA.md for the schema. The helpers below
 * derive everything else (a file at a checkpoint, a cumulative diff, unified text) from that data.
 * ------------------------------------------------------------------------------------------------------------- */
/*FILES_JSON*/

/** fileAt(project, path, cp): the content of a file at a checkpoint id ('c04' = before the session's first change; 'now' = the snapshot; 'final' = after the run). null: the file did not exist then. */
S.fileAt = function (project, path, cp) {
  var P = S.files[project];
  var v = P.versions[path];
  if (!v) return P.contents[path] === undefined ? null : P.contents[path];
  var order = ['c04'].concat(P.steps.map(function (s) { return s.id; }));
  var snapIdx = order.indexOf(P.snapshotCp);
  var idx = cp === 'now' ? snapIdx : cp === 'final' ? order.length - 1 : order.indexOf(cp);
  if (idx < 0) return null;
  var out = v[0][1];
  for (var i = 0; i < v.length; i++) if (order.indexOf(v[i][0]) <= idx) out = v[i][1];
  return out;
};
/** splitLines/diff: Myers-free LCS diff on lines, same hunk rules as the harness (3 lines of context, blocks closer than 6 lines merge). */
function splitLines(t) { if (t == null || t === '') return []; var a = t.split('\n'); if (a[a.length - 1] === '') a.pop(); return a; }
function lcsOps(a, b) {
  var n = a.length, m = b.length, i, j, L = [];
  for (i = 0; i <= n; i++) { L.push(new Array(m + 1).fill(0)); }
  for (i = n - 1; i >= 0; i--) for (j = m - 1; j >= 0; j--) L[i][j] = a[i] === b[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1]);
  var ops = []; i = 0; j = 0;
  while (i < n && j < m) {
    if (a[i] === b[j]) { ops.push(' '); i++; j++; }
    else if (L[i + 1][j] >= L[i][j + 1]) { ops.push('-'); i++; }
    else { ops.push('+'); j++; }
  }
  while (i < n) { ops.push('-'); i++; }
  while (j < m) { ops.push('+'); j++; }
  return ops;
}
/** diffText(old, new): {added, removed, hunks:[{oldStart,oldLines,newStart,newLines,lines:[{t,s}]}]} */
S.diffText = function (oldT, newT) {
  var a = splitLines(oldT), b = splitLines(newT), ops = lcsOps(a, b), C = 3;
  var added = ops.filter(function (o) { return o === '+'; }).length, removed = ops.filter(function (o) { return o === '-'; }).length;
  // change blocks in op indexes
  var blocks = [], k = 0, ai = 0, bi = 0;
  while (k < ops.length) {
    if (ops[k] === ' ') { ai++; bi++; k++; continue; }
    var a0 = ai, b0 = bi;
    while (k < ops.length && ops[k] !== ' ') { if (ops[k] === '-') ai++; else bi++; k++; }
    blocks.push({ a0: a0, a1: ai, b0: b0, b1: bi });
  }
  var hunks = [], i = 0;
  while (i < blocks.length) {
    var j = i;
    while (j + 1 < blocks.length && blocks[j + 1].a0 - blocks[j].a1 <= 2 * C) j++;
    var first = blocks[i], last = blocks[j];
    var s0 = Math.max(0, first.a0 - C), s1 = Math.min(a.length, last.a1 + C);
    var t0 = s0 + (first.b0 - first.a0), lines = [], x = s0, y = t0;
    for (var q = i; q <= j; q++) {
      var bl = blocks[q];
      while (x < bl.a0) { lines.push({ t: ' ', s: a[x] }); x++; y++; }
      for (; x < bl.a1; x++) lines.push({ t: '-', s: a[x] });
      for (; y < bl.b1; y++) lines.push({ t: '+', s: b[y] });
    }
    while (x < s1) { lines.push({ t: ' ', s: a[x] }); x++; y++; }
    var oldLines = s1 - s0, newLines = y - t0;
    hunks.push({ oldStart: oldLines === 0 ? s0 : s0 + 1, oldLines: oldLines, newStart: newLines === 0 ? t0 : t0 + 1, newLines: newLines, section: '', lines: lines });
    i = j + 1;
  }
  return { added: added, removed: removed, hunks: hunks };
};
/** stepDiff(project, cp): the diff of one checkpoint (what changed while cp was current), with hunks derived from the versions (same result as `git diff` for these files: P.gitHunks holds git's hunk headers for checking). */
S.stepDiff = function (project, cp) {
  var P = S.files[project], ids = P.steps.map(function (s) { return s.id; }), i = ids.indexOf(cp);
  if (i < 0) return [];
  var before = i === 0 ? 'c04' : ids[i - 1];
  return (P.diffs[cp] || []).map(function (f) {
    var o = S.fileAt(project, f.path, before), n = S.fileAt(project, f.path, cp), d = S.diffText(o, n);
    return { path: f.path, status: f.status, agents: f.agents, task: f.task, added: f.added, removed: f.removed, hunks: d.hunks };
  });
};
/** diffSince(project, cp, now): what `/diff cp` shows at `now` ('now' = the snapshot, 'final' = after the run): every file first touched in cp or later, from its state when cp began to its state at `now`.
 *  Each item: {path, status: added|modified|deleted, agents, added, removed, hunks}. */
S.diffSince = function (project, cp, now) {
  var P = S.files[project];
  var ids = P.steps.map(function (s) { return s.id; });
  var from = ids.indexOf(cp);
  if (from < 0) return [];
  var limit = now === 'final' ? ids.length - 1 : ids.indexOf(P.snapshotCp);
  var paths = {};
  for (var i = from; i <= limit; i++) (P.diffs[ids[i]] || []).forEach(function (f) { (paths[f.path] = paths[f.path] || { agents: {} }); f.agents.forEach(function (a) { paths[f.path].agents[a] = 1; }); });
  var before = from === 0 ? 'c04' : ids[from - 1];
  return Object.keys(paths).sort().map(function (p) {
    var o = S.fileAt(project, p, before), n = S.fileAt(project, p, ids[limit]);
    var d = S.diffText(o, n);
    if (/seed\/items\.json$/.test(p)) { var ad = 0, rm = 0; for (var s = from; s <= limit; s++) (P.diffs[ids[s]] || []).forEach(function (f) { if (f.path === p) { ad += f.added; rm += f.removed; } }); d.added = ad; d.removed = rm; }   // the stored text is the first rows only; the counts are the real ones
    return { path: p, status: o == null ? 'added' : n == null ? 'deleted' : 'modified', agents: Object.keys(paths[p].agents), added: d.added, removed: d.removed, hunks: d.hunks };
  }).filter(function (f) { return f.added || f.removed; });
};
/** unified(fileDiff): the text `/diff` prints for one file: "path (status)" is the caller's line; this is `--- a/path` onward (REAL shape: internal/checkpoint unifiedDiff). */
S.unified = function (f) {
  var out = ['--- ' + (f.status === 'added' ? '/dev/null' : 'a/' + f.path), '+++ ' + (f.status === 'deleted' ? '/dev/null' : 'b/' + f.path)];
  f.hunks.forEach(function (h) {
    out.push('@@ -' + h.oldStart + (h.oldLines === 1 ? '' : ',' + h.oldLines) + ' +' + h.newStart + (h.newLines === 1 ? '' : ',' + h.newLines) + ' @@' + (h.section ? ' ' + h.section : ''));
    h.lines.forEach(function (l) { out.push(l.t === '…' ? '… ' + l.s : l.t + l.s); });
  });
  return out.join('\n');
};
/** blame(project, path, now): [[firstLine, count, agent, checkpoint, task]]; agent '-' = written before the session. */
S.blame = function (project, path, now) { var P = S.files[project]; return (now === 'final' ? P.blameFinal : P.blameSnapshot)[path] || null; };
/** treeAt(project, now): the tree as the Files panel shows it: status A/M/D/- at `now`, owner and lease stripes in the writer's role colour. */
S.treeAt = function (project, now) {
  var P = S.files[project], fin = now === 'final';
  return P.tree.map(function (f) {
    var owner = fin ? f.ownerFinal : f.owner;
    var color = owner && S.teamById[owner] ? S.teamById[owner].color : (owner === 'main' ? S.roleColors.manager : null);
    return { path: f.path, dir: f.dir, size: fin ? f.sizeFinal : f.sizeSnapshot, status: fin ? f.finalStatus : f.status, owner: owner, task: fin ? f.taskFinal : f.task, checkpoint: fin ? f.checkpointFinal : f.checkpoint, lease: f.lease, leaseColor: f.lease && S.teamById[f.lease.agent] ? S.teamById[f.lease.agent].color : null, protected: f.protected, ask: f.ask, color: color, exists: fin ? true : f.existsAtSnapshot };
  });
};
S.projects = [
  { id: 'shop',       name: 'shop',       root: '~/projects/shop',       language: 'go + static web', module: 'example.com/shop',       files: 14 },
  { id: 'orders-api', name: 'orders-api', root: '~/projects/orders-api', language: 'go',              module: 'example.com/orders-api', files: 9 },
  { id: 'handbook',   name: 'handbook',   root: '~/projects/handbook',   language: 'markdown (docs)',  module: null,                     files: 31 },
];
S.projects[0].files = S.files.shop.tree.length; S.projects[1].files = S.files.orders.tree.length;

/* ---- checkpoints (/rewind): ids as the brief shows them (c04..c07 and older); the binary's own ids are cp_0007 style (realId) ---------------- */
S.checkpoints = (function () {
  var P = S.files.shop, out = [];
  var skipped = [
    { id: 'c01', time: '03:04:05', label: 'turn 1: ' + S.goal.command.slice(0, 60), note: 'the goal turn: nothing to put back' },
    { id: 'c02', time: '03:04:09', label: 'manager: plan and survey', note: 'nothing to put back' },
    { id: 'c03', time: '03:04:10', label: 'sc-1 sc-2 sc-3 worktrees', note: 'nothing to put back' },
    { id: 'c04', time: '03:04:12', label: 'turn 1', note: '0 files (skipped: nothing to put back)' },
  ];
  skipped.forEach(function (c) { out.push({ id: c.id, realId: 'cp_000' + c.id.slice(2), time: c.time, label: c.label, files: [], filesCount: 0, agents: [], skipped: true, future: false, note: c.note, diff: [] }); });
  P.steps.forEach(function (s, i) {
    var list = P.diffs[s.id] || [];
    var snapIdx = P.steps.map(function (x) { return x.id; }).indexOf(P.snapshotCp);
    out.push({ id: s.id, realId: 'cp_00' + s.id.slice(1), time: s.time, label: s.label, files: list.map(function (f) { return f.path; }), filesCount: list.length, agents: Array.from(new Set([].concat.apply([], list.map(function (f) { return f.agents; })))), tasks: Array.from(new Set(list.map(function (f) { return f.task; }).filter(Boolean))),
      added: list.reduce(function (a, f) { return a + f.added; }, 0), removed: list.reduce(function (a, f) { return a + f.removed; }, 0), skipped: false, future: i > snapIdx, diffRef: 'S.stepDiff("shop", "' + s.id + '")' });
  });
  return out;
})();
S.checkpoints.forEach(function (c) { Object.defineProperty(c, 'diff', { enumerable: false, get: function () { return c.skipped ? [] : S.stepDiff('shop', c.id); } }); });
S.checkpointNote = '/rewind lists checkpoints that touched a file, newest first (c07 03:04:38 3 files T4 catalogue handler); /rewind ID puts every file touched in ID or later back as it was when ID began (the agents are told to read them again); /diff ID is that difference (S.diffSince). The binary names them cp_0007; the brief\'s c07 is the same checkpoint.';
